window.AUTH=window.AUTH||{};window.AUTH["24-783"]={"d":"24-783","id":"2025/24-783","n":"Enbridge Energy, LP v. Nessel","briefs":[{"k":"petitioner","label":"Brief of petitioners Enbridge Energy, Limited Partnership, et al.","date":"2025-08-29","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/373220/20250829124313186_24-783_Petitioners%20Brief.pdf","side":"pet","n":54},{"k":"respondent","label":"Brief of respondent Dana Nessel, Attorney General of the State of Michigan, on behalf of the People of the State of Michigan","date":"2025-10-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/379565/20251014144257159_24-783%20Enbridge%20Brief%20of%20Respondent%20Final%20A.pdf","side":"res","n":84},{"k":"reply","label":"Reply of petitioners Enbridge Energy, Limited Partnership, et al.","date":"2025-11-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-783/384416/20251113151635213_No.%2024-783_Reply%20Brief.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r28_i4dk.pdf","tr":true,"items":[{"t":"case","label":"American Ins. Assoc. v. Garamendi","cite":"539 U.S. 396","y":2003,"id":"2002/02-722","sc":1,"by":{"0":"43"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"by":{"0":"27, 30"}},{"t":"case","label":"Arellano v. McDonough","cite":"598 U.S. 1","y":2023,"id":"2022/21-432","sc":1,"by":{"0":"33, 37","1":"51","2":"20, 21"},"q":[{"src":"brief","b":1,"text":"is a traditional feature of American jurisprudence and a background principle against which Congress drafts limitations periods.","cite":"598 U.S. at 6"},{"src":"brief","b":1,"text":"presumption is rebutted if ‘there [is] good reason to believe that Congress did not want the equitable tolling doctrine to apply.’","cite":"598 U.S. at 7"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"extinguis[h] a tardy claim (the function of a statute of limitations),","cite":"598 U. S. 1, 7"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"The presumption is rebutted if `there [is] good reason to believe that Congress did not want the equitable tolling doctrine to apply.'","cite":"598 U. S., at 7"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"to extend [the Page Proof deadline] still further tPhroeugnh dthiendogctrPineuofbeqliucitaablteitoollning,","cite":"598 U. S., at 7"},{"src":"argument","who":"Justice Jackson","text":"What do you do with Arellano, which is a more recent, I think, or one of the most recent cases that we have that talk about this doctrine and comes out the other way?"},{"src":"argument","who":"Mr. Bursch","text":"Justice Jackson, I'm delighted that you brought up Arellano."},{"src":"argument","who":"Mr. Bursch","text":"But -- but here's the important thing about Arellano. It was the text. It said, \"unless specifically provided otherwise in this chapter.\" That is the clearest command that Holland requires."}]},{"t":"case","label":"Ayers v. Watson","cite":"113 U.S. 594","y":1885,"id":"scdb/1884-152","sc":1,"by":{"0":"30"}},{"t":"case","label":"Back Doctors Ltd v. Metro. Prop. & Cas. Ins. Co.","cite":"637 F.3d 827","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/637/827/","by":{"0":"50"},"q":[{"src":"brief","b":0,"text":"[t]here is no presumption against federal jurisdiction in general, or removal in particular.","cite":"637 F.3d 827, 830"}]},{"t":"case","label":"Boechler, P.C. v. Comm’r of Internal Revenue","cite":"596 U.S. 199","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/199/","sc":1,"by":{"0":"2, 23, 25–29, 31–36, 40–41, 45","1":"28, 29, 42","2":"6, 8, 12"},"q":[{"src":"brief","b":0,"text":"Equitable tolling is a traditional feature of American jurisprudence and a background principle against which Congress drafts limitations periods.","cite":"596 U.S. 199, 208–09"},{"src":"brief","b":0,"text":"[N]ot all procedural requirements fit that bill.","cite":"596 U.S. at 203"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[j]urisdictional requirements cannot be waived or forfeited, must be raised by courts sua sponte, and, as relevant to this case, do not allow for equitable exceptions.","cite":"596 U. S. 199, 203"},{"src":"argument","who":"Mr. Bursch","text":"Like Boechler, 1446(b) does not expressly prohibit equitable tolling, and its short 30-day time limit is directed at the defendant, not the court, which is why it's placed in a procedural section."},{"src":"argument","who":"Mr. Bursch","text":"You can do what you did in Boechler, where the -- the law firm clearly dropped the ball, in the Court's words, simply decided that equitable tolling applied, and then remanded it to the lower courts."},{"src":"argument","who":"Mr. Bursch","text":"And I -- I start with our affirmative case, which is Boechler, just like 14 -- or, I'm sorry, just like the -- the statute in Boechler, 1446(b) does not expressly prohibit equitable tolling, it's got the short 30-day time deadline, and it's directed at the defendant, not at the court."}]},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"by":{"0":"35"}},{"t":"case","label":"Breuer v. Jim’s Concrete of Brevard","cite":"538 U.S. 691","y":2003,"id":"2002/02-337","sc":1,"by":{"0":"50"},"q":[{"src":"brief","b":0,"text":"whatever apparent force this argument might have claimed when Shamrock was handed down has been qualified by later statutory development.","cite":"538 U.S. 691, 697–98"},{"src":"argument","who":"Mr. Bursch","text":"First, as the Chamber brief explains at pages 20 to 21, in Dart and Breuer, this Court made clear that it doesn't provide any kind of a strict construction in this context."}]},{"t":"case","label":"Brown v. Demco","cite":"792 F.2d 478","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/792/478/","by":{"0":"30"}},{"t":"case","label":"Caterpillar, Inc. v. Lewis","cite":"519 U.S. 61","y":1996,"id":"1996/95-1263","sc":1,"by":{"0":"5, 29–31, 34, 39"},"q":[{"src":"brief","b":0,"text":"a procedure calling for expeditious superintendence by district courts.","cite":"519 U.S. at 76"}]},{"t":"case","label":"Chi., Rock Island, & Pac. Ry. Co. v. Martin","cite":"178 U.S. 245","y":1900,"id":"scdb/1899-057","sc":1,"by":{"0":"47"}},{"t":"case","label":"Cogdell v. Wyeth","cite":"366 F.3d 1245","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/366/1245/","by":{"0":"41"}},{"t":"case","label":"Enbridge Energy, LP v. Whitmer","cite":"135 F.4th 467","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/135/467/","by":{"0":"17"}},{"t":"case","label":"French v. Hay","cite":"89 U.S. 238","y":1874,"id":"scdb/1874-171","sc":1,"by":{"0":"30"}},{"t":"case","label":"Ft. Bend County, Tex. v. Davis","cite":"587 U.S. 541","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/541/","sc":1,"by":{"0":"28"}},{"t":"case","label":"Gillis v. Louisiana","cite":"294 F.3d 755","y":2002,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/294/755/","by":{"0":"47","2":"12"}},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"by":{"0":"15, 18, 21, 35","1":"13"},"q":[{"src":"brief","b":0,"text":"Whatever the virtues of the [Grable] standard, it is anything but clear.","cite":"545 U.S. at 321"}]},{"t":"case","label":"Greenlaw v. U.S.","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"by":{"0":"37"}},{"t":"case","label":"Grubb v. Donegal Mut. Ins. Co.","cite":"935 F.2d 57","y":1991,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/935/57/","by":{"0":"42"}},{"t":"case","label":"Grubbs v. Gen. Elec. Credit Corp.","cite":"405 U.S. 699","y":1972,"id":"1971/71-257","sc":1,"by":{"0":"5"}},{"t":"case","label":"Hamer v. Neighborhood Hos. Servs. Of Chi.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"by":{"0":"27, 29","1":"25"}},{"t":"case","label":"Harrow v. Dep’t of Def.","cite":"601 U.S. 480","y":2024,"id":"2023/23-21","sc":1,"by":{"0":"23, 27, 28, 32, 34, 36","1":"33","2":"5, 6, 7"},"q":[{"src":"brief","b":0,"text":"That is true whether or not the [deadline] is ‘framed in mandatory terms.’","cite":"601 U.S. at 484"},{"src":"brief","b":0,"text":"against the backdrop of judicial doctrines creating exceptions, and typically expects those doctrines to apply.","cite":"601 U.S. at 483"},{"src":"brief","b":2,"text":"nonjurisdictional timing rules … presumptively subject to equitable tolling.","cite":"601 U.S. at 489"},{"src":"argument","who":"Mr. Bursch","text":"And I think that's why most recently in Harrow, the 2024 case which also involved appeals, the Court said the presumption applies to non-jurisdictional timing rules."},{"src":"argument","who":"Mr. Bursch","text":"I'm saying, under Lozano, Young, Nutraceutical, and Harrow, it's functionally a statute of limitations the way the Court has defined that phrase for purposes of these inquiries about traditional equitable authority."},{"src":"argument","who":"Mr. Bursch","text":"That's the kind of thing that we would encourage the Sixth Circuit to decide on remand, as you did in Boechler and also in Harrow, you know, sending back that hard question."}]},{"t":"case","label":"Heimeshoff v. Hartford Life & Acc. Ins. Co.","cite":"571 U.S. 99","y":2013,"id":"2013/12-729","sc":1,"by":{"0":"40"},"q":[{"src":"brief","b":0,"text":"well equipped to apply traditional doctrines,","cite":"571 U.S. 99, 114"}]},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"26, 27, 28, 29"},"q":[{"src":"brief","b":0,"text":"tried in recent cases to bring some discipline to the use of this term.","cite":"562 U.S. at 435"},{"src":"brief","b":0,"text":"Among the types of rules that should not be described as jurisdictional are … ‘claim-processing rules.’","cite":"562 U.S. at 435"}]},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"by":{"0":"23, 32, 36, 40, 46, 47","1":"28, 29, 42, 53","2":"2, 10, 13"},"q":[{"src":"brief","b":0,"text":"will not construe a statute to displace courts’ traditional equitable authority absent the clearest command.","cite":"560 U.S. at 646"},{"src":"brief","b":0,"text":"area of the law where equity finds a comfortable home.","cite":"560 U.S. at 647"},{"src":"brief","b":1,"text":"federal removal from state to federal court is an ‘area of the law where equity finds a comfortable home.’","cite":"560 U.S. at 647"},{"src":"brief","b":1,"text":"is entitled to equitable tolling only if he shows (1) that he has been pursuing his rights diligently, and (2) that some extraordinary circumstance stood in his way and prevented timely filing.","cite":"560 U.S. at 649"},{"src":"argument","who":"Mr. Bursch","text":"So, under Holland, the Court's presumption, it presumes that federal courts retain their traditional equitable authority absent the clearest command."},{"src":"argument","who":"Mr. Bursch","text":"It said, \"unless specifically provided otherwise in this chapter.\" That is the clearest command that Holland requires. And what the Court said was that that was a textual book \"indicating that Congress enumerated an exhaustive list of exceptions with each confined to its specific terms.\" We don't have anything like that in the removal statute, anything like that in the IRS statute."},{"src":"argument","who":"Mr. Bursch","text":"Well, the -- the baseline is that Holland says you need the clearest command to rebut the presumption. So now burden of proof shifts to the attorney general."}]},{"t":"case","label":"Huffman v. Pursue, Ltd.","cite":"420 U.S. 592","y":1975,"id":"1974/73-296","sc":1,"by":{"0":"44"}},{"t":"case","label":"Irwin v. Dep’t of Veterans Affs.","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"by":{"0":"23, 40, 43","1":"33, 43","2":"7, 13"},"q":[{"src":"brief","b":0,"text":"Federal courts have typically extended equitable relief only sparingly.","cite":"498 U.S. at 96"},{"src":"argument","who":"Mr. Bursch","text":"And when we think about this traditional equitable authority, this isn't something that just developed in Irwin or the Court's tolling cases."}]},{"t":"case","label":"United States ex rel. Kennedy v. Tyler","cite":"269 U.S. 13","y":1925,"id":"scdb/1925-001","sc":1,"by":{"0":"44"},"q":[{"src":"brief","b":0,"text":"trade and diplomatic relations with Canada.","cite":"269 U.S. 13, 19"}]},{"t":"case","label":"Lozano v. Montoya Alveraz","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"by":{"0":"23","1":"3, 26, 27, 28","2":"4, 5"},"q":[{"src":"brief","b":0,"text":"effectively extends an otherwise discrete limitations period set by Congress.","cite":"572 U.S. 1, 10"},{"src":"brief","b":0,"text":"Congress is presumed to incorporate equitable tolling","cite":"572 U.S. at 11"},{"src":"brief","b":1,"text":"fundamentally a question of statutory intent.","cite":"572 U.S. at 10"},{"src":"brief","b":1,"text":"only applied that presumption to statutes of limitations.","cite":"572 U.S. at 13"},{"src":"brief","b":2,"text":"was … presumptively subject to equitable tolling.","cite":"572 U.S. at 14"},{"src":"brief","b":2,"text":"return the child immediately if the other parent requests return within one year.","cite":"572 U.S. at 4"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"ha[s] only applied [the presumption of equitable tolling] to statutes of limitations.","cite":"572 U. S. 1, 13–14"},{"src":"argument","who":"Mr. Bursch","text":"First, in Lozano, the Court unanimously announced that the statute of limitations concept is a functional one, it's not a strict one. So you don't need to have a claim being cut off."},{"src":"argument","who":"Mr. Bursch","text":"Well, Justice Sotomayor, that's why Lozano makes clear that this is a functional test and why you crossed that Rubicon of having to lose a claim in both --"},{"src":"argument","who":"Justice Sotomayor","text":"Meaning, in Lozano, the question was did the parent -- and we said no, that even though the parent didn't get automatic return of the child, it still got circumstances in which the child wouldn't be returned."}]},{"t":"case","label":"Mata v. Lynch","cite":"576 U.S. 143","y":2015,"id":"2014/14-185","sc":1,"by":{"0":"34"}},{"t":"case","label":"Murphy Bros., Inc. v. Michetti Pipe Stringing, Inc.","cite":"526 U.S. 344","y":1999,"id":"1998/97-1909","sc":1,"by":{"0":"46, 50","1":"35, 46, 49"},"q":[{"src":"brief","b":1,"text":"atypical state commencement and complaint filing procedures.","cite":"526 U.S. 344, 351– 53"}]},{"t":"case","label":"Northern Pac. R.R. v. Austin","cite":"135 U.S. 315","y":1890,"id":"scdb/1889-227","sc":1,"by":{"0":"30–31"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"586 U.S. 188","y":2019,"id":"2018/17-1094","sc":1,"by":{"0":"2–3, 33–34, 45","1":"25, 33","2":"6, 7, 12, 13"},"q":[{"src":"brief","b":0,"text":"the simple fact that a deadline is phrased in an unqualified manner does not necessarily establish that tolling is unavailable.","cite":"586 U.S. at 193"},{"src":"brief","b":1,"text":"they are ‘unalterable’ if properly raised by an opposing party.","cite":"586 U.S. at 192"},{"src":"brief","b":1,"text":"[w]hether a rule precludes equitable tolling turns not on its jurisdictional character but rather on whether the text of the rule leaves room for such flexibility.","cite":"586 U.S. 188, 192"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"The mere fact that a time limit lacks jurisdictional force, however, does not render it malleable in every respect.","cite":"586 U. S. 188, 192"},{"src":"argument","who":"Mr. Bursch","text":"And then, finally, the unanimous opinion in Nutraceutical, where, again, the plaintiff lost their -- their right to an interlocutory appeal of the denial of class certification, but they did not lose their claim."},{"src":"argument","who":"Mr. Bursch","text":"That -- that's why I point you to Young and also your opinion in Nutraceutical because, in those cases too, no one lost a claim. In -- in Nutraceutical, there was no right to interlocutory appeal other than that granted by rule, and yet the Court looked for a clear intent to preclude tolling."},{"src":"argument","who":"Mr. Bursch","text":"But, in Nutraceutical, you still had the ability to have an appeal at the end of final judgment. You were just losing a mechanism to enforce your arguments in the same way that we're losing our right to removal."}]},{"t":"case","label":"Powers v. Chesapeake & O Ry.","cite":"169 U.S. 92","y":1898,"id":"scdb/1897-061","sc":1,"by":{"0":"31, 32, 40","1":"51, 52","2":"10, 11"},"q":[{"src":"brief","b":2,"text":"after the time mentioned in the act ha[d] expired.","cite":"169 U.S. at 98"}]},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"by":{"0":"26"}},{"t":"case","label":"Rexford v. Brunswick-Balke-Collender Co.","cite":"228 U.S. 339","y":1913,"id":"scdb/1912-168","sc":1,"by":{"0":"31"}},{"t":"case","label":"Riley v. Bondi","cite":"145 S. Ct. 2190","y":2025,"id":"2024/23-1270","sc":1,"by":{"0":"27, 28"}},{"t":"case","label":"Robertson v. U.S. Bank, N.A.","cite":"831 F.3d 757","y":2016,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/757/","by":{"0":"41, 46"}},{"t":"case","label":"Rock Hemp Corp. v. Dunn","cite":"51 F.4th 693","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/51/693/","by":{"0":"41"}},{"t":"case","label":"Rothner v. City of Chicago","cite":"879 F.2d 1402","y":1989,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/879/1402/","by":{"0":"42"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"leave[s] the ball in Congress’ court.","cite":"598 U.S. 411, 416–417"}]},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"27–29, 32","1":"30, 33, 34"},"q":[{"src":"brief","b":0,"text":"time limitation may be emphatic, yet not jurisdictional.","cite":"568 U.S. at 155"},{"src":"brief","b":0,"text":"such a principle is likely to be a realistic assessment of legislative intent.","cite":"568 U.S. at 159"}]},{"t":"case","label":"Shamrock Oil & Gas Corp. v. Sheets","cite":"313 U.S. 100","y":1941,"id":"scdb/1940-150","sc":1,"by":{"0":"50","1":"2, 32"},"q":[{"src":"brief","b":1,"text":"to provide for the determination of controversies in their courts.","cite":"313 U.S. 100, 109"},{"src":"brief","b":1,"text":"may be restricted only by the action of Congress in conformity to the Judiciary Articles of the Constitution.","cite":"313 U.S. at 108"},{"src":"argument","who":"Mr. Bursch","text":"But the two cases that they most rely on, Syngenta and Shamrock Oil, those both strictly construed jurisdiction. And, of course, we have to strictly construe federal subject matter jurisdiction when you're talking about state courts' interests."}]},{"t":"case","label":"Sprint Commc’ns, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"by":{"0":"44"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. U.S. ex rel. Rigsby","cite":"580 U.S. 26","y":2016,"id":"2016/15-513","sc":1,"by":{"0":"39"},"q":[{"src":"argument","who":"Mr. Bursch","text":"As in State Farm, Congress's decision to expressly direct a remand for lack of jurisdiction but not for procedural defects suggests that courts retain their traditional equitable authority to excuse procedural defects."}]},{"t":"case","label":"Taylor v. Medtronic, Inc.","cite":"15 F.4th 148","y":2021,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/15/148/","by":{"0":"46–47"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"by":{"0":"35","1":"42, 43"},"q":[{"src":"brief","b":1,"text":"has already effectively allowed for equitable tolling.","cite":"524 U.S. at 48"},{"src":"argument","who":"Ms. Sherman","text":"It said that in Beggerly. And this Court has typically deferred, as it did in Arellano, the question of estoppel because it -- you know, especially if it's not raised in a case."}]},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"by":{"0":"25, 38, 47, 48","1":"33, 35, 36, 40, 42, 49"},"q":[{"src":"brief","b":0,"text":"one can … plausibly read as containing an implied ‘equitable tolling’ exception.","cite":"519 U.S. 347, 350"},{"src":"brief","b":1,"text":"that Congress did not intend courts to read other unmentioned, open-ended, ‘equitable’ exceptions into the statute that it wrote.","cite":"519 U.S. at 352"},{"src":"brief","b":1,"text":"rather than delegate to the courts a generalized power to do so wherever a court concludes that equity so requires.","cite":"519 U.S. at 353"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"good reason to believe that Congress did not want the equitable tolling doctrine to apply,","cite":"519 U. S., at 350"},{"src":"argument","who":"Ms. Sherman","text":"We haven't talked a lot today about the -- the exceptions, but when you look at the -- the clear mandatory language, \"shall file in 30 days,\" and that's supported by a very comprehensive scheme that has at least six exceptions, and those exceptions are interrelated, they are -- the default deadline of 30 days is repeated multiple times, similar to in Brockamp and similar to in -- in Arellano, you have these many exceptions that are taking a situation outside of the default rule."}]},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"by":{"0":"33"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"23, 27–30, 34","2":"14, 21"},"q":[{"src":"brief","b":0,"text":"traditional tools of statutory construction must plainly show that Congress imbued a procedural bar with jurisdictional consequences.","cite":"575 U.S. at 410"},{"src":"argument","who":"Mr. Bursch","text":"Wong said it's likely to be a realistic assessment of legislative intent, as well as a practically useful rule of interpretation. Why is that?"}]},{"t":"case","label":"Weeks v. Fidelity & Cas. Co. of N.Y.","cite":"218 F.2d 503","y":1955,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/218/503/","by":{"0":"46"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"by":{"0":"27, 30"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"by":{"0":"32","1":"27, 28","2":"1, 3, 4, 7"},"q":[{"src":"brief","b":2,"text":"limitations period because it prescribes a period within which certain rights (namely, priority and nondischargeability in bankruptcy) may be enforced.","cite":"535 U.S. at 47"}]},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"by":{"0":"29–30, 34","1":"28, 29","2":"6, 7"},"q":[{"src":"brief","b":2,"text":"triggered by the event giving rise","cite":"455 U.S. 385, 393–94"},{"src":"argument","who":"Mr. Bursch","text":"And this Court said in Zipes -- that was a unanimous Justice White opinion -- that those two equitable doctrines and the doctrine of tolling travel together."}]},{"t":"case","label":"Andrus v. Glover Constr. Co.","cite":"446 U.S. 608","y":1980,"id":"1979/79-48","sc":1,"by":{"1":"36"}},{"t":"case","label":"Babbitt v. Clark","cite":"103 U.S. 606","y":1880,"id":"scdb/1880-165","sc":1,"by":{"1":"50"},"q":[{"src":"brief","b":1,"text":"[t]he right to remove a suit from a State court … is statutory, and to effect a transfer of jurisdiction all the requirements of the statute must be followed.","cite":"103 U.S. 606, 610"},{"src":"argument","who":"Ms. Sherman","text":"And this Court had said over and over in a long line of cases from Babbitt versus Clark on that when the deadline is missed, remand is necessary."},{"src":"argument","who":"Ms. Sherman","text":"We cite cases on pages 50 to 51 of our brief starting from Babbitt versus Clark in 1880 onward where this Court has strictly enforced the deadline, and there's a reason for that."}]},{"t":"case","label":"Balt. & Ohio R.R. Co. v. Burns","cite":"124 U.S. 165","y":1888,"id":"scdb/1887-094","sc":1,"by":{"1":"50"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"1":"39"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[w]hen Congress includes particular language in one section of a statute but omits it from a neighbor, we normally understand that difference in language to convey a difference in meaning.","cite":"598 U. S. 85, 94"}]},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"can … determine when, and under what conditions","cite":"551 U.S. 205, 212–13"}]},{"t":"case","label":"Burt v. Titlow","cite":"571 U.S. 12","y":2013,"id":"2013/12-414","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"a foundational principle of our federal system: State courts are adequate forums for the vindication of federal rights.","cite":"571 U.S. 12, 19"}]},{"t":"case","label":"Dean v. United States","cite":"556 U.S. 568","y":2009,"id":"2008/08-5274","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"resist reading words … into a statute that do not appear on its face,","cite":"556 U.S. 568, 572"}]},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"1":"34"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"1":"43"}},{"t":"case","label":"Edrington v. Jefferson","cite":"111 U.S. 770","y":1884,"id":"scdb/1883-269","sc":1,"by":{"1":"51"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"by":{"1":"26"},"q":[{"src":"brief","b":1,"text":"In statutory interpretation disputes, a court’s proper starting point lies in a careful examination of the ordinary meaning and structure of the law itself.","cite":"588 U.S. 427, 436"}]},{"t":"case","label":"Glass v. Goeckel","cite":"703 N.W.2d 58","y":2005,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/703/58/","by":{"1":"8"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"1":"25, 47"},"q":[{"src":"brief","b":1,"text":"calling a rule nonjurisdictional does not mean that it is not mandatory or that a timely objection can be ignored.","cite":"565 U.S. 134, 146"},{"src":"brief","b":1,"text":"can never be waived or forfeited.","cite":"565 U.S. at 141"}]},{"t":"case","label":"Great N. R. Co. v. Alexander","cite":"246 U.S. 276","y":1918,"id":"scdb/1917-082","sc":1,"by":{"1":"32"}},{"t":"case","label":"Gregory v. Hartley","cite":"113 U.S. 742","y":1885,"id":"scdb/1884-170","sc":1,"by":{"1":"50"}},{"t":"case","label":"Hallstrom v. Tillamook","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"by":{"1":"26, 27, 28, 29, 35, 54","2":"4, 5"},"q":[{"src":"brief","b":1,"text":"are not at liberty to create an exception where Congress has declined to do so.","cite":"493 U.S. 20, 27"},{"src":"brief","b":1,"text":"generally filed by trained lawyers who are presumed to be aware of statutory requirements.","cite":"493 U.S. at 28"}]},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"by":{"1":"36"}},{"t":"case","label":"Hoyt v. Lane Constr. Co.","cite":"927 F.3d 287","y":2019,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/287/","by":{"1":"48"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Ida.","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"by":{"1":"8"},"q":[{"src":"brief","b":1,"text":"infused with a public trust the State itself is bound to respect.","cite":"521 U.S. at 283"}]},{"t":"case","label":"Ill. Cent. R.R. Co. v. Illinois","cite":"146 U.S. 387","y":1892,"id":"scdb/1892-038","sc":1,"by":{"1":"8"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"by":{"1":"30, 33"},"q":[{"src":"brief","b":1,"text":"seeks to achieve a broader system-related goal, such as facilitating the administration of claims … or promoting judicial efficiency,","cite":"552 U.S. 130, 133–34"}]},{"t":"case","label":"Kan. City, Fort Scott & Memphis R.R. Co. v. Daughtry","cite":"138 U.S. 298","y":1891,"id":"scdb/1890-112","sc":1,"by":{"1":"50"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of Am.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"1":"21"},"q":[{"src":"brief","b":1,"text":"possess only that power authorized by Constitution and statute, which is not to be expanded by judicial decree.","cite":"511 U.S. 375, 377"}]},{"t":"case","label":"Mackay v. Uinta Dev. Co.","cite":"229 U.S. 173","y":1913,"id":"scdb/1912-223","sc":1,"by":{"1":"31, 51","2":"8, 9, 10"},"q":[{"src":"brief","b":1,"text":"the litigant has the right to rely upon the statute, and to insist that, in compliance with its terms, the case shall be taken from the state to the Federal court … at the proper time.","cite":"229 U.S. 173, 176"}]},{"t":"case","label":"Manning v. Amy","cite":"140 U.S. 137","y":1891,"id":"scdb/1890-234","sc":1,"by":{"1":"48"}},{"t":"case","label":"Manrique v. United States","cite":"581 U.S. 116","y":2017,"id":"2016/15-7250","sc":1,"by":{"1":"25"}},{"t":"case","label":"Martin v. Hunter’s Lessee","cite":"14 U.S. 304","y":1816,"id":"1789-1850/14us304","sc":1,"by":{"1":"31, 50","2":"8"}},{"t":"case","label":"Martin’s Adm’r v. Balt. & Ohio R.R. Co.","cite":"151 U.S. 673","y":1894,"id":"scdb/1893-139","sc":1,"by":{"1":"51"}},{"t":"case","label":"McIntosh v. United States","cite":"601 U.S. 330","y":2024,"id":"2023/22-7386","sc":1,"by":{"1":"25"},"q":[{"src":"brief","b":1,"text":"This Court has identified three types of time limits: (1) jurisdictional deadlines; (2) mandatory claimprocessing rules; and (3) time-related directives.","cite":"601 U.S. 330, 337"},{"src":"brief","b":1,"text":"the relevant action cannot be taken after the deadline has passed.","cite":"601 U.S. at 337"}]},{"t":"case","label":"McNeil v. United States","cite":"508 U.S. 106","y":1993,"id":"1992/92-6033","sc":1,"by":{"1":"29"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Manning","cite":"578 U.S. 374","y":2016,"id":"2015/14-1132","sc":1,"by":{"1":"32"},"q":[{"src":"brief","b":1,"text":"Out of respect for state courts, this Court has time and again declined to construe federal jurisdictional statutes more expansively than their language, most fairly read, requires.","cite":"578 U.S. 374, 389"}]},{"t":"case","label":"Nedtweg v. Wallace","cite":"208 N.W. 51","y":1926,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./208/51/","by":{"1":"8"}},{"t":"case","label":"Oscar Mayer & Co. v. Evans","cite":"441 U.S. 750","y":1979,"id":"1978/78-275","sc":1,"by":{"1":"29"}},{"t":"case","label":"Phx. Mut. Life Ins. Co. v. Walrath","cite":"117 U.S. 365","y":1886,"id":"scdb/1885-186","sc":1,"by":{"1":"50"}},{"t":"case","label":"Pullman Palace Car Co. v. Speck","cite":"113 U.S. 84","y":1885,"id":"scdb/1884-092","sc":1,"by":{"1":"45, 48, 51"},"q":[{"src":"brief","b":1,"text":"the defendant, who had a right of removal, and failed to exercise it at the earliest period possible, should be presumed to have acquiesced in the forum chosen by the plaintiff.","cite":"113 U.S. 84, 85"},{"src":"brief","b":1,"text":"[wa]s not permitted unreasonably to delay this election during all the period incident to the preparation of the case.","cite":"113 U.S. at 86"}]},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"by":{"1":"26, 34"},"q":[{"src":"brief","b":1,"text":"[T]he mandatory ‘shall’ normally creates an obligation impervious to judicial discretion.","cite":"578 U.S. at 639"},{"src":"brief","b":1,"text":"may not excuse [the requirement], even to take [special] circumstances into account,","cite":"578 U.S. at 639"}]},{"t":"case","label":"Rotkiske v. Klemm","cite":"589 U.S. 8","y":2019,"id":"2019/18-328","sc":1,"by":{"1":"36"},"q":[{"src":"brief","b":1,"text":"Congress has shown that it knows how to adopt the omitted language or provision.","cite":"589 U.S. 8, 14"}]},{"t":"case","label":"S. Pac. Co. v. Stewart","cite":"245 U.S. 359","y":1917,"id":"scdb/1917-002","sc":1,"by":{"1":"31, 51","2":"8, 9"},"q":[{"src":"brief","b":1,"text":"[i]t is essential to the removal of a cause that the petition, provided for by the statute, be filed … within the time fixed by statute, unless the time be in some manner waived.","cite":"245 U.S. 359, 363"}]},{"t":"case","label":"Snapper, Inc. v. Redan","cite":"171 F.3d 1249","y":1999,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/171/1249/","by":{"1":"47"}},{"t":"case","label":"Syngenta Crop Prot., Inc. v. Henson","cite":"537 U.S. 28","y":2002,"id":"2002/01-757","sc":1,"by":{"1":"32","2":"11"},"q":[{"src":"brief","b":1,"text":"a suit commenced in a state court must remain there until cause is shown for its transfer under some act of Congress.","cite":"537 U.S. 28, 32"},{"src":"brief","b":1,"text":"statutory procedures for removal are to be strictly construed,","cite":"537 U.S. at 32"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"is entirely a creature of statute[,] and `a suit commenced in a state court must remain there until cause is shown for its transfer under some act of Congress.'","cite":"537 U. S. 28, 32"},{"src":"argument","who":"Mr. Bursch","text":"But the two cases that they most rely on, Syngenta and Shamrock Oil, those both strictly construed jurisdiction. And, of course, we have to strictly construe federal subject matter jurisdiction when you're talking about state courts' interests."}]},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"1":"36, 43"},"q":[{"src":"brief","b":1,"text":"Where Congress explicitly enumerates certain exceptions to a general [requirement], additional exceptions are not to be implied.","cite":"534 U.S. 19, 28"},{"src":"brief","b":1,"text":"the express exception [in § 1446(b)(3)] would be rendered insignificant, if not wholly superfluous.","cite":"534 U.S. at 31"}]},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"the potentially harsh consequence of barring a meritorious claim before the plaintiff has a reasonable chance to assert his legal rights.","cite":"444 U.S. 111, 126"}]},{"t":"case","label":"Wilson v. Intercollegiate (Big Ten) Conference Athletic Ass’n","cite":"668 F.2d 962","y":1982,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/668/962/","by":{"1":"48, 49"},"q":[{"src":"brief","b":1,"text":"to prevent the delay and waste of resources involved in starting a case over in a second court after significant proceedings … have taken place in the first court,","cite":"668 F.2d at 965"}]},{"t":"usc","label":"9 U.S.C. § 205","url":"https://www.law.cornell.edu/uscode/text/9/205","by":{"1":"7"}},{"t":"usc","label":"12 U.S.C. § 1819","url":"https://www.law.cornell.edu/uscode/text/12/1819","subs":["(b)(2)(B)"],"by":{"1":"7"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"1":"16"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(d)","(e)","(e)(1)","(a)","(e)(1)(B)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 23, 38, 40, 44, 49, 38, 40, 6, 23, 38, 44","2":"11, 17, 20, 19, 20, 19"},"q":[{"src":"brief","b":2,"text":"even if the action to be removed could not have been brought in a district court as an original matter.","cite":"28 U.S.C. 1441(e)(1)(B)"},{"src":"brief","b":2,"text":"Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown.","cite":"28 U.S.C. 1441(d)"}]},{"t":"usc","label":"28 U.S.C. § 1442a","url":"https://www.law.cornell.edu/uscode/text/28/1442a","stext":{"head":"§1442a. Members of armed forces sued or prosecuted","paras":[[0,"A civil or criminal prosecution in a court of a State of the United States against a member of the armed forces of the United States on account of an act done under color of his office or status, or in respect to which he claims any right, title, or authority under a law of the United States respecting the armed forces thereof, or under the law of war, may at any time before the trial or final hearing thereof be removed for trial into the district court of the United States for the district where it is pending in the manner prescribed by law, and it shall thereupon be entered on the docket of the district court, which shall proceed as if the cause had been originally commenced therein and shall have full power to hear and determine the cause."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1442a?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 23, 39","2":"18–19"},"q":[{"src":"brief","b":2,"text":"at any time before the trial or final hearing.","cite":"28 U.S.C. 1442a"}]},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(a)","(b)","(b)(1)","(b)(2)","(b)(2)(A)","(b)(2)(B)","(b)(2)(C)","(b)(3)","(c)(1)","(c)(3)(B)"],"stext":{"head":"§1446. Procedure for removal of civil actions","paras":[[0,"(a) Generally.—A defendant or defendants desiring to remove any civil action from a State court shall file in the district court of the United States for the district and division within which such action is pending a notice of removal signed pursuant to Rule 11 of the Federal Rules of Civil Procedure and containing a short and plain statement of the grounds for removal, together with a copy of all process, pleadings, and orders served upon such defendant or defendants in such action."],[0,"(b) Requirements; Generally.—(1) The notice of removal of a civil action or proceeding shall be filed within 30 days after the receipt by the defendant, through service or otherwise, of a copy of the initial pleading setting forth the claim for relief upon which such action or proceeding is based, or within 30 days after the service of summons upon the defendant if such initial pleading has then been filed in court and is not required to be served on the defendant, whichever period is shorter."],[0,"(2)(A) When a civil action is removed solely under section 1441(a), all defendants who have been properly joined and served must join in or consent to the removal of the action."],[0,"(B) Each defendant shall have 30 days after receipt by or service on that defendant of the initial pleading or summons described in paragraph (1) to file the notice of removal."],[0,"(C) If defendants are served at different times, and a later-served defendant files a notice of removal, any earlier-served defendant may consent to the removal even though that earlier-served defendant did not previously initiate or consent to removal."],[0,"(3) Except as provided in subsection (c), if the case stated by the initial pleading is not removable, a notice of removal may be filed within thirty days after receipt by the defendant, through service or otherwise, of a copy of an amended pleading, motion, order or other paper from which it may first be ascertained that the case is one which is or has become removable."],[0,"(c) Requirements; Removal Based on Diversity of Citizenship.—(1) A case may not be removed under subsection (b)(3) on the basis of jurisdiction conferred by section 1332 more than 1 year after commencement of the action, unless the district court finds that the plaintiff has acted in bad faith in order to prevent a defendant from removing the action."],[0,"(2) If removal of a civil action is sought on the basis of the jurisdiction conferred by section 1332(a), the sum demanded in good faith in the initial pleading shall be deemed to be the amount in controversy, except that—"],[1,"(A) the notice of removal may assert the amount in controversy if the initial pleading seeks—"],[2,"(i) nonmonetary relief; or"],[2,"(ii) a money judgment, but the State practice either does not permit demand for a specific sum or permits recovery of damages in excess of the amount demanded; and"],[1,"(B) removal of the action is proper on the basis of an amount in controversy asserted under subparagraph (A) if the district court finds, by the preponderance of the evidence, that the amount in controversy exceeds the amount specified in section 1332(a)."],[0,"(3)(A) If the case stated by the initial pleading is not removable solely because the amount in controversy does not exceed the amount specified in section 1332(a), information relating to the amount in controversy in the record of the State proceeding, or in responses to discovery, shall be treated as an \"other paper\" under subsection (b)(3)."],[0,"(B) If the notice of removal is filed more than 1 year after commencement of the action and the district court finds that the plaintiff deliberately failed to disclose the actual amount in controversy to prevent removal, that finding shall be deemed bad faith under paragraph (1)."],[0,"(d) Notice to Adverse Parties and State Court.—Promptly after the filing of such notice of removal of a civil action the defendant or defendants shall give written notice thereof to all adverse parties and shall file a copy of the notice with the clerk of such State court, which shall effect the removal and the State court shall proceed no further unless and until the case is remanded."],[0,"(e) Counterclaim in 337 Proceeding.—With respect to any counterclaim removed to a district court pursuant to section 337(c) of the Tariff Act of 1930, the district court shall resolve such counterclaim in the same manner as an original complaint under the Federal Rules of Civil Procedure, except that the payment of a filing fee shall not be required in such cases and the counterclaim shall relate back to the date of the original complaint in the proceeding before the International Trade Commission under section 337 of that Act."],[0,"(g) 1 Where the civil action or criminal prosecution that is removable under section 1442(a) is a proceeding in which a judicial order for testimony or documents is sought or issued or sought to be enforced, the 30-day requirement of subsection (b) of this section and paragraph (1) of section 1455(b) is satisfied if the person or entity desiring to remove the proceeding files the notice of removal not later than 30 days after receiving, through service, notice of any such proceeding."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1446?type=usc&year=mostrecent&link-type=html"},"by":{"1":"5, 35, i, 2, 3, 4, 5, 15, 21, 23, 24, 25, 26, 28, 33, 34, 36, 37, 39, 40, 44, 40, 47, 5, 37, 5, 23, 37, 3, 5, 15, 17, 23, 37, 40, 43, 53, 6, 38, 43, 38","2":"1, 2, 7, 13–21, 1, 3, 15, 15, 16"},"q":[{"src":"brief","b":1,"text":"shall be filed within 30 days.","cite":"28 U.S.C. § 1446(b)(1)"},{"src":"brief","b":2,"text":"even though that earlier-served defendant did not previously initiate or consent to removal.","cite":"28 U.S.C. 1446(b)(2)(B)"}]},{"t":"usc","label":"28 U.S.C. § 1447","url":"https://www.law.cornell.edu/uscode/text/28/1447","subs":["(c)"],"stext":{"head":"§1447. Procedure after removal generally","paras":[[0,"(a) In any case removed from a State court, the district court may issue all necessary orders and process to bring before it all proper parties whether served by process issued by the State court or otherwise."],[0,"(b) It may require the removing party to file with its clerk copies of all records and proceedings in such State court or may cause the same to be brought before it by writ of certiorari issued to such State court."],[0,"(c) A motion to remand the case on the basis of any defect other than lack of subject matter jurisdiction must be made within 30 days after the filing of the notice of removal under section 1446(a). If at any time before final judgment it appears that the district court lacks subject matter jurisdiction, the case shall be remanded. An order remanding the case may require payment of just costs and any actual expenses, including attorney fees, incurred as a result of the removal. A certified copy of the order of remand shall be mailed by the clerk to the clerk of the State court. The State court may thereupon proceed with such case."],[0,"(d) An order remanding a case to the State court from which it was removed is not reviewable on appeal or otherwise, except that an order remanding a case to the State court from which it was removed pursuant to section 1442 or 1443 of this title shall be reviewable by appeal or otherwise."],[0,"(e) If after removal the plaintiff seeks to join additional defendants whose joinder would destroy subject matter jurisdiction, the court may deny joinder, or permit joinder and remand the action to the State court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1447?type=usc&year=mostrecent&link-type=html"},"by":{"1":"47","2":"11, 14"}},{"t":"usc","label":"28 U.S.C. § 1453","url":"https://www.law.cornell.edu/uscode/text/28/1453","subs":["(b)"],"stext":{"head":"§1453. Removal of class actions","paras":[[0,"(a) Definitions.—In this section, the terms \"class\", \"class action\", \"class certification order\", and \"class member\" shall have the meanings given such terms under section 1332(d)(1)."],[0,"(b) In General.—A class action may be removed to a district court of the United States in accordance with section 1446 (except that the 1-year limitation under section 1446(c)(1) shall not apply), without regard to whether any defendant is a citizen of the State in which the action is brought, except that such action may be removed by any defendant without the consent of all defendants."],[0,"(c) Review of Remand Orders.—"],[1,"(1) In general.—Section 1447 shall apply to any removal of a case under this section, except that notwithstanding section 1447(d), a court of appeals may accept an appeal from an order of a district court granting or denying a motion to remand a class action to the State court from which it was removed if application is made to the court of appeals not more than 10 days after entry of the order."],[1,"(2) Time period for judgment.—If the court of appeals accepts an appeal under paragraph (1), the court shall complete all action on such appeal, including rendering judgment, not later than 60 days after the date on which such appeal was filed, unless an extension is granted under paragraph (3)."],[1,"(3) Extension of time period.—The court of appeals may grant an extension of the 60-day period described in paragraph (2) if—"],[2,"(A) all parties to the proceeding agree to such extension, for any period of time; or"],[2,"(B) such extension is for good cause shown and in the interests of justice, for a period not to exceed 10 days."],[1,"(4) Denial of appeal.—If a final judgment on the appeal under paragraph (1) is not issued before the end of the period described in paragraph (2), including any extension under paragraph (3), the appeal shall be denied."],[0,"(d) Exception.—This section shall not apply to any class action that solely involves—"],[1,"(1) a claim concerning a covered security as defined under section 16(f)(3) of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 1) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(2) a claim that relates to the internal affairs or governance of a corporation or other form of business enterprise and arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(3) a claim that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1453?type=usc&year=mostrecent&link-type=html"},"by":{"1":"6, 38","2":"17, 17"}},{"t":"usc","label":"28 U.S.C. § 1454","url":"https://www.law.cornell.edu/uscode/text/28/1454","subs":["(b)","(b)(2)"],"stext":{"head":"§1454. Patent, plant variety protection, and copyright cases","paras":[[0,"(a) In General.—A civil action in which any party asserts a claim for relief arising under any Act of Congress relating to patents, plant variety protection, or copyrights may be removed to the district court of the United States for the district and division embracing the place where the action is pending."],[0,"(b) Special Rules.—The removal of an action under this section shall be made in accordance with section 1446, except that if the removal is based solely on this section—"],[1,"(1) the action may be removed by any party; and"],[1,"(2) the time limitations contained in section 1446(b) may be extended at any time for cause shown."],[0,"(c) Clarification of Jurisdiction in Certain Cases.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in the civil action because the State court from which the civil action is removed did not have jurisdiction over that claim."],[0,"(d) Remand.—If a civil action is removed solely under this section, the district court—"],[1,"(1) shall remand all claims that are neither a basis for removal under subsection (a) nor within the original or supplemental jurisdiction of the district court under any Act of Congress; and"],[1,"(2) may, under the circumstances specified in section 1367(c), remand any claims within the supplemental jurisdiction of the district court under section 1367."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1454?type=usc&year=mostrecent&link-type=html"},"by":{"1":"40, 7, 23, 39, 44, 49","2":"18, 20"}},{"t":"usc","label":"28 U.S.C. § 1455","url":"https://www.law.cornell.edu/uscode/text/28/1455","subs":["(b)(1)"],"by":{"1":"39, 48, 49"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(d)(2)"],"by":{"1":"7"}},{"t":"law","label":"Pub. L. No. 112-63","url":"https://www.govinfo.gov/link/plaw/112/public/63","by":{"1":"35"}},{"t":"case","label":"Burnett v. New York Cent. R.R. Co.","cite":"380 U.S. 424","y":1965,"id":"1964/437","sc":1,"by":{"2":"14"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"by":{"2":"13"}},{"t":"case","label":"Gamage v. Peal","cite":"217 F. Supp. 384","y":1962,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./217/384/","by":{"2":"19"}},{"t":"case","label":"Kamen v. Kemper Fin. Servs., Inc.","cite":"500 U.S. 90","y":1991,"id":"1990/90-516","sc":1,"by":{"2":"23"}},{"t":"case","label":"Lebron v. Nat’l R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"by":{"2":"23"}},{"t":"case","label":"Loftin v. Rush","cite":"767 F.2d 800","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/767/800/","by":{"2":"12"},"q":[{"src":"argument","who":"Mr. Bursch","text":"It was a much different kind of federal interest but one that I think was significant in the Loftin case, which is the Eleventh Circuit decision that created the equitable tolling doctrine for removal statutes in the Eleventh Circuit 40 years ago."}]},{"t":"case","label":"Margan v. Chemetron Fire Sys., Inc.","cite":"954 F. Supp. 1127","y":1997,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./954/1127/","by":{"2":"19"}},{"t":"case","label":"S. Pac. Co. v. Stewart","cite":"245 U.S. 562","y":1918,"id":"scdb/1917-217","sc":1,"by":{"2":"9"}},{"t":"case","label":"United States v. Locke","cite":"471 U.S. 84","y":1985,"id":"1984/83-1394","sc":1,"by":{"2":"7"}},{"t":"usc","label":"28 U.S.C. § 1369","url":"https://www.law.cornell.edu/uscode/text/28/1369","by":{"2":"19"}},{"t":"usc","label":"38 U.S.C. § 5110","url":"https://www.law.cornell.edu/uscode/text/38/5110","subs":["(b)"],"by":{"2":"20, 21"}}]};